package com.example.practice;

import org.jpos.iso.ISOException;
import org.jpos.iso.ISOMsg;
import org.jpos.iso.ISOUtil;
import org.jpos.iso.MUX;

import java.util.concurrent.atomic.AtomicLong;

/**
 * The gateway's side of the upstream link. Terminals send their requests to {@link #forward};
 * the gateway relays each one to the acquirer's host through one QMUX, as one terminal.
 */
public class Upstream {
    private final MUX mux;
    private final String gatewayId;
    private final AtomicLong sent = new AtomicLong();

    public Upstream(MUX mux, String gatewayId) {
        this.mux = mux;
        this.gatewayId = gatewayId;
    }

    /** Relays a terminal's request and returns the response the terminal should get, or null. */
    public ISOMsg forward(ISOMsg fromTerminal) throws ISOException {
        ISOMsg up = upstreamCopy(fromTerminal);
        ISOMsg response = mux.request(up, 30000);
        return response == null ? null : forTerminal(response, fromTerminal);
    }

    /** The message the host receives: the terminal's request, sent by the gateway. */
    ISOMsg upstreamCopy(ISOMsg fromTerminal) throws ISOException {
        ISOMsg up = (ISOMsg) fromTerminal.clone();
        up.set(41, gatewayId);
        up.set(11, nextStan());
        return up;
    }

    /** The response as the terminal expects it: an answer to the request it sent. */
    ISOMsg forTerminal(ISOMsg response, ISOMsg fromTerminal) throws ISOException {
        ISOMsg down = (ISOMsg) response.clone();
        down.set(11, fromTerminal.getString(11));
        down.set(41, fromTerminal.getString(41));
        return down;
    }

    /** The STAN of the next message the gateway sends on this link. */
    String nextStan() {
        long n = sent.incrementAndGet();
        return ISOUtil.zeropad(((n - 1) % 999999) + 1, 6);
    }
}

import com.example.practice.Upstream;
import org.jpos.iso.ISOMsg;
import org.jpos.iso.ISOResponseListener;
import org.jpos.iso.MUX;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) throws Exception {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            Host host = new Host();
            Upstream gw = new Upstream(host, "GW000009");
            ISOMsg a = gw.forward(purchase("40210001", "000088"));
            ISOMsg b = gw.forward(purchase("40210002", "000088"));
            System.out.println("host saw: 41=" + host.received.get(0).getString(41) + " 11=" + host.received.get(0).getString(11)
                    + ", 41=" + host.received.get(1).getString(41) + " 11=" + host.received.get(1).getString(11));
            System.out.println("terminal 1 got: " + a.getMTI() + " 39=" + a.getString(39) + " 41=" + a.getString(41) + " 11=" + a.getString(11));
            System.out.println("terminal 2 got: " + b.getMTI() + " 39=" + b.getString(39) + " 41=" + b.getString(41) + " 11=" + b.getString(11));
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }

    private static ISOMsg purchase(String terminal, String stan) throws Exception {
        ISOMsg m = new ISOMsg("0200");
        m.set(3, "000000");
        m.set(4, "000000003150");
        m.set(11, stan);
        m.set(41, terminal);
        return m;
    }

    /** A host that approves at once and keeps what it received. */
    static final class Host implements MUX {
        final List<ISOMsg> received = new ArrayList<>();

        @Override public ISOMsg request(ISOMsg m, long timeout) {
            received.add(m);
            ISOMsg r = (ISOMsg) m.clone();
            try { r.setResponseMTI(); r.set(39, "00"); } catch (Exception e) { throw new IllegalStateException(e); }
            return r;
        }
        @Override public void request(ISOMsg m, long t, ISOResponseListener l, Object h) { l.responseReceived(request(m, t), h); }
        @Override public void send(ISOMsg m) { received.add(m); }
        @Override public boolean isConnected() { return true; }
    }
}

